UPDATE INT_SERVERFUNCTION SET NAME = COALESCE(NULL, NAME), DESCRIPTION = COALESCE(NULL, DESCRIPTION), TYPE = COALESCE(NULL, TYPE), JDBC_ID = NULL, CODE = COALESCE('SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CONTA_ID'',x.CONTA_ID,''NOME'',x.NOME,''CODIGO'',x.CODIGO,''VALOR'',x.VALOR)) FROM (SELECT z.CONTA_ID, cc.NOME, cc.CODIGO, SUM(z.VALOR) AS VALOR FROM (SELECT o.CONTA_ID, o.VALOR FROM ORCAMENTO o WHERE o.CICLO_ID = {{cicloId}} AND o.CR_ID = {{crId}} AND o.MES = {{mes}} UNION ALL SELECT op.CONTA_ID, op.VALOR FROM ORCAMENTO_PACOTE op WHERE op.CICLO_ID = {{cicloId}} AND op.CR_ID = {{crId}} AND op.MES = {{mes}} AND EXISTS (SELECT 1 FROM PACOTE_STATUS ps WHERE ps.CICLO_ID = op.CICLO_ID AND ps.DRIVER_ID = op.DRIVER_ID AND ps.STATUS IN (''SUBMETIDO'',''APROVADO''))) z JOIN CONTA_CONTABIL cc ON cc.ID = z.CONTA_ID GROUP BY z.CONTA_ID, cc.NOME, cc.CODIGO) x),JSON_ARRAY()) AS ORC,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CONTA_ID'',x.CONTA_ID,''VALOR'',x.VALOR)) FROM (SELECT rc.CONTA_ID, SUM(rc.VALOR) AS VALOR FROM REALIZADO_CONTABIL rc WHERE rc.ANO = {{ano}} AND rc.CR_ID = {{crId}} AND rc.MES = {{mes}} GROUP BY rc.CONTA_ID) x),JSON_ARRAY()) AS REAL_ROWS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CONTA_ID'',x.CONTA_ID,''VALOR'',x.VALOR)) FROM (SELECT rc.CONTA_ID, SUM(rc.VALOR) AS VALOR FROM REALIZADO_CONTABIL rc WHERE rc.ANO = {{anoPrev}} AND rc.CR_ID = {{crId}} AND rc.MES = {{mes}} GROUP BY rc.CONTA_ID) x),JSON_ARRAY()) AS REAL_ANT', CODE), PUBLIC_EXECUTION = COALESCE(NULL, PUBLIC_EXECUTION), CRON_EXPRESSION = NULL, CRON_INPUT_JSON = NULL WHERE NAME = 'hotResumoCrMes';
